// Look for the visualization type indicator/picker
let viz = document.querySelector('[data-testid="viz-picker"], [class*="viz-picker"], [class*="visualization-picker"], [aria-label*="Visualization"]');
if (viz) { viz.innerText; } else {
  // Try to find any element that shows the current viz type (like "Stat", "Text", "Table")
  let els = Array.from(document.querySelectorAll('div, button, span'));
  let matches = els.filter(e => e.offsetParent !== null && /^(Stat|Text|Table|Time series|Gauge|Bar gauge|Pie chart|Logs|Histogram|Heatmap|State timeline|Status history|Bar chart|Canvas|Node Graph|Flame Graph|Trend|Datagrid)$/i.test(e.innerText.trim()));
  matches.slice(0,10).map(e => ({tag: e.tagName, cls: e.className, text: e.innerText.trim().substring(0,60), parent: e.parentElement?.className?.substring(0,60)}));
}

