(function() {
  // Find the Availability panel menu button
  let allMenus = document.querySelectorAll('button[aria-label*="Menu for panel"]');
  for(let btn of allMenus) {
    let heading = btn.closest('section, [role="region"]')?.querySelector('h2');
    if(heading && heading.innerText.includes('Availability')) {
      return btn.outerHTML.substring(0,200);
    }
  }
  return 'not found: ' + allMenus.length + ' menu buttons';
})()
